select id, dept_name, location, budget, dense_rank() over (partition by dept_name order by budget desc nulls last) as budget_dense_rank, sum(budget) over w_ordered as cumulative_budget, rank() over w_hist as budget_rank from departments window w_ordered as (order by budget, id rows between unbounded preceding and current row), w_hist as (partition by dept_name order by budget desc nulls first)
